import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Quick check for null case
    if np.mean(feats.y) < 0.05 or np.mean(feats.y) > 0.95:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Fast feature selection based on variance and correlation
    variances = np.var(feats.x, axis=0)
    high_var_indices = np.where(variances > 0.01)[0]

    if len(high_var_indices) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use top features based on t-statistics
    t_stats = []
    for i in high_var_indices:
        if np.std(feats.x[:, i]) > 1e-8:  # Avoid division by zero
            t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            t_stats.append((abs(t_stat), i))

    if not t_stats:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Sort by t-statistic magnitude
    t_stats.sort(reverse=True)
    selected_indices = [i for _, i in t_stats[:10]]

    # Get feature IDs
    selected_features = [feats.ids[i] for i in selected_indices]

    # Remove near-duplicates quickly
    final_features = []
    seen = set()
    for fid in selected_features:
        if fid in seen:
            continue
        is_duplicate = False
        for existing_fid in final_features:
            try:
                corr = np.corrcoef(feats.x[:, feats.column(fid)], 
                                 feats.x[:, feats.column(existing_fid)])[0,1]
                if abs(corr) >= 0.6:
                    is_duplicate = True
                    break
            except:
                pass
        if not is_duplicate:
            final_features.append(fid)
            seen.add(fid)

    if not final_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select drivers (top 4 by t-score)
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Get top drivers
    driver_scores = []
    for i, fid in enumerate(final_features):
        idx = feats.column(fid)
        if np.std(feats.x[:, idx]) > 1e-8:
            t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, idx], feats.x[feats.y==0, idx])
            driver_scores.append((abs(t_stat), fid))

    if driver_scores:
        driver_scores.sort(reverse=True)
        drivers = [fid for _, fid in driver_scores[:MAX_DRIVERS]]
        columns = final_features

        # Add product terms for highly correlated pairs
        for i, fid1 in enumerate(columns):
            for j, fid2 in enumerate(columns[i+1:], i+1):
                try:
                    corr = np.corrcoef(feats.x[:, feats.column(fid1)], 
                                     feats.x[:, feats.column(fid2)])[0,1]
                    if abs(corr) >= 0.6:
                        products.append((fid1, fid2))
                except:
                    pass

        # Loadings based on t-scores
        for fid in columns:
            idx = feats.column(fid)
            if np.std(feats.x[:, idx]) > 1e-8:
                t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, idx], feats.x[feats.y==0, idx])
                loadings[fid] = t_stat

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

